import struct,zlib

def read(path):
 data=open(path,'rb').read();pos=8;comp=b'';chunks=[]
 while pos<len(data):
  n=struct.unpack('>I',data[pos:pos+4])[0];key=data[pos+4:pos+8];v=data[pos+8:pos+8+n];pos+=12+n
  chunks.append((key,len(v)))
  if key==b'IHDR':w,h,depth,typ,_,_,_=struct.unpack('>IIBBBBB',v)
  if key==b'IDAT':comp+=v
 if depth!=8 or typ not in (2,6): raise ValueError((depth,typ))
 bpp={2:3,6:4}[typ];raw=zlib.decompress(comp);rows=[];prev=[0]*(w*bpp)
 for y in range(h):
  off=y*(w*bpp+1);f=raw[off];row=list(raw[off+1:off+1+w*bpp])
  for i,x in enumerate(row):
   a=row[i-bpp] if i>=bpp else 0;b=prev[i];c=prev[i-bpp] if i>=bpp else 0
   if f==1:x+=a
   elif f==2:x+=b
   elif f==3:x+=(a+b)//2
   elif f==4:
    p=a+b-c;pa=abs(p-a);pb=abs(p-b);pc=abs(p-c)
    x+=a if pa<=pb and pa<=pc else b if pb<=pc else c
   row[i]=x%256
  rows.append([tuple(row[x:x+bpp]) for x in range(0,len(row),bpp)]);prev=row
 return w,h,typ,rows,chunks
if __name__=='__main__':
 import sys
 w,h,t,p,c=read(sys.argv[1]); print(w,h,t,c)
 for row in p[40:58]:
  print(''.join(' .:-=+*#%@'[9*(255-min(pixel[:3]))//255] for pixel in row[34:70]))
PY
