import java.awt.Color;
import java.io.*;
import java.nio.charset.*;
import java.nio.file.*;
import java.util.*;

/** Command-line and stream interface for the diagram renderer. */
public class Main {
    static class Flag {
        final String shortName, name;
        final boolean argument;
        Flag(String s, String n, boolean a) {shortName=s;name=n;argument=a;}
    }
    static final Flag[] FLAGS = {
        new Flag("S","no-shadows",false), new Flag("A","no-antialias",false),
        new Flag("r","round-corners",false), new Flag("E","no-separation",false),
        new Flag("d","debug",false), new Flag("v","verbose",false),
        new Flag("h","html",false), new Flag("e","encoding",true),
        new Flag("s","scale",true), new Flag("t","tabs",true),
        new Flag("b","background",true), new Flag("T","transparent",false),
        new Flag("o","overwrite",false), new Flag("W","fixed-slope",false),
        new Flag(null,"help",false), new Flag(null,"svg",false),
        new Flag(null,"svg-font-url",true)
    };
    static class Entry {
        Flag flag; String value;
        Entry(Flag f,String v) {flag=f;value=v;}
    }
    static class Options {
        ArrayList<Entry> entries=new ArrayList<>();
        ArrayList<String> files=new ArrayList<>();
        boolean svg, html, debug, overwrite, round, noSeparation, noShadows, noAA, fixed;
        boolean quiet;
        float scale=1f;
        int tabs=8;
        Color background=Color.WHITE;
        Charset charset=StandardCharsets.UTF_8;
        String fontURL;
        String first(String n) {for(Entry e:entries) if(e.flag.name.equals(n))return e.value;return null;}
        boolean has(String n) {for(Entry e:entries)if(e.flag.name.equals(n))return true;return false;}
        void log(String line) {if(!quiet)System.out.println(line);}
    }
    static class UsageError extends Exception {
        boolean help=true, lower=false;
        UsageError(String s) {super(s);}
    }
    static Flag shortFlag(char c) {
        for(Flag f:FLAGS) if(f.shortName!=null && f.shortName.equals(""+c)) return f;
        return null;
    }
    static Flag longFlag(String text, String original) throws UsageError {
        for(Flag f:FLAGS) if(f.name.equals(text)) return f;
        ArrayList<Flag> matches=new ArrayList<>();
        for(Flag f:FLAGS) if(f.name.startsWith(text))matches.add(f);
        if(matches.size()==1)return matches.get(0);
        if(matches.isEmpty())return null;
        StringJoiner j=new StringJoiner(", ");for(Flag f:matches)j.add("'"+f.name+"'");
        throw new UsageError("Ambiguous option: '"+original+"'  (could be: "+j+")");
    }
    static boolean looksLikeOption(String s) {
        if(s.equals("--"))return true;
        if(!s.startsWith("-")||s.length()==1)return false;
        String n=s.replaceFirst("^-{1,2}","").split("=",2)[0];
        try {if(longFlag(n,s)!=null)return true;}catch(Exception e){return true;}
        return !s.startsWith("--")&&shortFlag(s.charAt(1))!=null;
    }
    static Options parse(String[] args)throws UsageError {
        Options o=new Options();boolean end=false;
        for(int i=0;i<args.length;i++) {
            String a=args[i];
            if(end||!a.startsWith("-")||a.equals("-")){o.files.add(a);continue;}
            if(a.equals("--")){end=true;continue;}
            String n=a.substring(a.startsWith("--")?2:1), attached=null;
            int eq=n.indexOf('='); if(eq>=0){attached=n.substring(eq+1);n=n.substring(0,eq);}
            Flag f;
            if(!a.startsWith("--")&&n.length()==1) f=shortFlag(n.charAt(0));
            else f=longFlag(n,a.substring(0,eq>=0?a.indexOf('='):a.length()));
            if(f!=null) {
                if(f.argument) {
                    if(attached==null) {
                        if(i+1>=args.length||looksLikeOption(args[i+1]))throw new UsageError("Missing argument for option: "+n);
                        attached=args[++i];
                    }
                    if(!a.startsWith("--")&&eq>=0&&n.length()==1)attached="="+attached;
                    o.entries.add(new Entry(f,attached));
                } else {
                    o.entries.add(new Entry(f,null));
                    if(attached!=null)o.files.add(attached);
                }
                continue;
            }
            if(a.startsWith("--"))throw new UsageError("Unrecognized option: "+a);
            String cluster=a.substring(1);
            for(int j=0;j<cluster.length();j++) {
                f=shortFlag(cluster.charAt(j));
                if(f==null)throw new UsageError("Unrecognized option: "+a);
                String val=null;
                if(f.argument) {
                    if(j+1<cluster.length()){val=cluster.substring(j+1);j=cluster.length();}
                    else {
                        if(i+1>=args.length||looksLikeOption(args[i+1]))throw new UsageError("Missing argument for option: "+f.shortName);
                        val=args[++i];
                    }
                }
                o.entries.add(new Entry(f,val));
                if(f.argument)break;
            }
        }
        return o;
    }
    static void configure(Options o)throws UsageError {
        o.svg=o.has("svg");o.html=o.has("html");o.debug=o.has("debug");
        o.overwrite=o.has("overwrite");o.round=o.has("round-corners");o.noSeparation=o.has("no-separation");
        o.noShadows=o.has("no-shadows");o.noAA=o.has("no-antialias");o.fixed=o.has("fixed-slope");
        o.fontURL=o.first("svg-font-url");
        try {
            if(o.has("scale"))o.scale=Float.parseFloat(o.first("scale"));
            if(o.has("tabs"))o.tabs=Integer.parseInt(o.first("tabs"));
            if(o.has("background")) {
                String b=o.first("background");
                if(b.length()!=6&&b.length()!=8)throw new UsageError("Error: Cannot interpret \""+b+"\" as background colour. It needs to be a 6- or 8-digit hex number, depending on whether you have transparency or not (same as HTML).");
                long x;
                try{x=Long.parseLong(b,16);}catch(NumberFormatException ex){throw new NumberFormatException("For input string: \""+b+"\"");}
                if(b.length()==6)o.background=new Color((int)x);
                else o.background=new Color((int)(x>>24)&255,(int)(x>>16)&255,(int)(x>>8)&255,(int)x&255);
            }
        }catch(NumberFormatException ex){throw new UsageError("Error: "+ex.getMessage());}
        if(o.has("transparent"))o.background=new Color(255,255,255,0);
        if(o.has("encoding")) {
            try{o.charset=Charset.forName(o.first("encoding"));}
            catch(Exception ex){UsageError e=new UsageError("Error: "+o.first("encoding"));e.help=false;throw e;}
        }
    }
    static void help(boolean lower) {
        try(InputStream in=Main.class.getResourceAsStream("/help.txt")) {
            String t=new String(in.readAllBytes(),StandardCharsets.UTF_8);
            if(lower)t=t.replace("<INPFILE> [OUTFILE]","<inpfile> [outfile]");
            System.out.print(t);
        }catch(IOException e){throw new RuntimeException(e);}
    }
    static void banner(Options o) {
        o.log("\nditaa version 0.11, Copyright (C) 2004--2017  Efstathios (Stathis) Sideris\n");
        o.log("Running with options:");
        for(Entry e:o.entries)o.log(e.flag.name+(e.flag.argument?" = "+e.value:""));
    }
    static String outputName(String input, String suffix, boolean overwrite) {
        File f=new File(input).getAbsoluteFile();String n=f.getName();
        int p=n.lastIndexOf('.');if(p>=0)n=n.substring(0,p);
        File result=new File(f.getParentFile(),n+suffix);
        if(!overwrite) {
            int i=2;while(result.exists())result=new File(f.getParentFile(),n+"_"+(i++)+suffix);
        }
        return result.toString();
    }
    static void originalFailure(String kind, boolean stdIn) {
        if(kind.equals("blank")) {
            System.err.print("Exception in thread \"main\" java.lang.IndexOutOfBoundsException: toIndex = 1\n"
                +"\tat java.base/java.util.AbstractList.subListRangeCheck(AbstractList.java:507)\n"
                +"\tat java.base/java.util.ArrayList.subList(ArrayList.java:1138)\n"
                +"\tat org.stathissideris.ascii2image.text.TextGrid.initialiseWithLines(TextGrid.java:1540)\n"
                +"\tat org.stathissideris.ascii2image.text.TextGrid.loadFrom(TextGrid.java:1518)\n"
                +"\tat org.stathissideris.ascii2image.core.CommandLineConverter.main(CommandLineConverter.java:"+(stdIn?"221":"233")+")\n");
        } else {
            System.err.print("Exception in thread \"main\" java.lang.NullPointerException\n"
                +"\tat org.stathissideris.ascii2image.graphics.FontMeasurer.getWidthFor(FontMeasurer.java:72)\n"
                +"\tat org.stathissideris.ascii2image.graphics.Diagram.<init>(Diagram.java:553)\n"
                +"\tat org.stathissideris.ascii2image.core.CommandLineConverter.main(CommandLineConverter.java:252)\n");
        }
    }
    static int run(String[] args)throws Exception {
        if(args.length==0){help(false);return 0;}
        Options o;
        try {
            o=parse(args);
            if(o.has("help")){help(false);return 0;}
            configure(o);
            if(o.files.isEmpty()) {UsageError e=new UsageError("Error: Please provide the input file filename");e.lower=true;throw e;}
        }catch(UsageError e){System.err.println(e.getMessage());if(e.help)help(e.lower);return 2;}
        String input=o.files.get(0);
        String output=o.files.size()>1?o.files.get(1):input.equals("-")?"-":outputName(input,o.svg?".svg":".png",o.overwrite);
        if(o.html) {
            banner(o);
            String htmlOut=o.files.size()>1?o.files.get(1):outputName(input,"_processed.html",true);
            HtmlMode.convert(input,htmlOut,o);
            return 0;
        }
        o.quiet=output.equals("-");
        banner(o);
        byte[] bytes;
        if(input.equals("-")) {o.log("Reading standard input");bytes=System.in.readAllBytes();}
        else {
            o.log("Reading file: "+input);
            try{bytes=Files.readAllBytes(Paths.get(input));}
            catch(IOException e){System.err.println("Error: File "+input+" does not exist");return 1;}
        }
        Drawing drawing;
        try {drawing=new Drawing(new String(bytes,o.charset),o);}
        catch(Drawing.EmptyLines e){originalFailure("blank",input.equals("-"));return 1;}
        catch(Drawing.InvalidSize e){originalFailure("font",input.equals("-"));return 1;}
        if(o.debug){o.log("Using grid:");drawing.printGrid();}
        drawing.build();
        o.log("Rendering to file: "+output);
        try {
            OutputStream dest=output.equals("-")?System.out:new FileOutputStream(output);
            drawing.write(dest);
            if(!output.equals("-"))dest.close();
        }catch(IOException e){System.err.println("Error: Cannot write to file "+output);return 1;}
        o.log("Done in 0sec");
        return 0;
    }
    public static void main(String[] args) {
        int code;
        try{code=run(args);}
        catch(Exception ex){ex.printStackTrace();code=1;}
        if(code!=0)System.exit(code);
    }
}
EOF"}

