                int end=last+1;Label l=new Label();l.row=y;l.col=start;l.actualLength=end-start;l.length=Math.max(2,l.actualLength);
                l.text=new String(textGrid[y],start,Math.min(l.length,width-start));while(l.text.length()<l.length)l.text+=" ";
