import java.io.*;
import java.nio.file.*;
import java.util.*;
import java.util.regex.*;

/** HTML mode keeps the source markup intact apart from diagram pre blocks. */
class HtmlMode {
    static String attr(String attributes,String name) {
        Matcher m=Pattern.compile("(?i)(?:^|\\s)"+name+"\\s*=\\s*(?:\"([^\"]*)\"|'([^']*)'|([^\\s>]+))").matcher(attributes);
        if(!m.find())return null;return m.group(1)!=null?m.group(1):m.group(2)!=null?m.group(2):m.group(3);
    }
    static void convert(String input,String output,Main.Options o) {
        String source;
        try{source=Files.readString(Paths.get(input),o.charset);}catch(Exception ex){System.err.println("Error: cannot read file "+input);return;}
        if(new File(output).exists()&&!o.overwrite) {
            System.out.println("Error: File "+output+" exists. If you would like to overwrite it, please use the --overwrite option.");return;
        }
        System.out.print("Converting HTML file ("+input+" -> "+output+")... ");
        Pattern pattern=Pattern.compile("(?is)<pre\\b([^>]*)>(.*?)</pre\\s*>");Matcher m=pattern.matcher(source);
        StringBuffer converted=new StringBuffer();HashMap<String,String> diagrams=new HashMap<>();int sequence=1;
        File parent=new File(output).getParentFile();File images=new File(parent,"images");String ext=o.svg?".svg":".png";
        while(m.find()) {
            if(!"textdiagram".equals(attr(m.group(1),"class")))continue;
            String id=attr(m.group(1),"id");if(id==null)id="ditaa_diagram_"+(sequence++);
            String filename=id+ext;String diagram=m.group(2);
            diagrams.put(new File(images,filename).toString(),diagram);
            m.appendReplacement(converted,Matcher.quoteReplacement("<img src=\"images/"+filename+"\" />"));
        }
        m.appendTail(converted);
        if(diagrams.isEmpty()) {System.out.println("\nHTML document does not contain any <pre> tags with their class attribute set to \"textdiagram\". Nothing to do.");return;}
        try{Files.writeString(Paths.get(output),converted.toString(),o.charset);}catch(Exception ex){System.err.println("Error while writing to file "+output);return;}
        System.out.println("done\nGenerating diagrams... ");images.mkdirs();
        for(Map.Entry<String,String> e:diagrams.entrySet()) {
            File file=new File(e.getKey());
            if(file.exists()&&!o.overwrite){System.out.println("\t"+file+" exists, skipping");continue;}
            System.out.println("\t"+file);
            try {
                Drawing d=new Drawing(e.getValue(),o);if(o.debug)d.printGrid();d.build();
                try(OutputStream out=new FileOutputStream(file)){d.write(out);}
            }catch(Exception ex){System.err.println("Error while writing to file "+file);}
        }
        System.out.println("\n...done");
    }
}
