    static final int[] BASELINES={0,0,5,9,11,14,17,20,23,26,28,32,35,38,40,44,46,50,52,55,58,61,64,67,69,73,75,79,81,84,87,90,93,96,98,102,104,107,110,113,116,119,121};

    Drawing(String source,Main.Options opts)throws EmptyLines,InvalidSize {
        options=opts;
        String[] split=source.split("\\r\\n|\\r|\\n");
        if(split.length==0)throw new EmptyLines();
        int count=split.length;
        while(count>1&&split[count-1].trim().isEmpty())count--;
        ArrayList<String> lines=new ArrayList<>();int w=0;
        for(int i=0;i<count;i++) {
            String s=split[i];StringBuilder expanded=new StringBuilder();
            for(int j=0;j<s.length();j++) {
                char c=s.charAt(j);
                if(c=='\t') {
                    int num=opts.tabs-expanded.length()%opts.tabs;
                    for(int k=0;k<num;k++)expanded.append(' ');
                } else expanded.append(c);
            }
            s=expanded.toString();lines.add(s);w=Math.max(w,s.length());
        }
        width=w+4;height=count+4;grid=new char[height][width];
        for(char[] row:grid)Arrays.fill(row,' ');
        for(int y=0;y<count;y++)lines.get(y).getChars(0,lines.get(y).length(),grid[y+2],2);
        for(int y=0;y<height;y++)for(int x=1;x<width-2;x++) {
            if((grid[y][x]=='o'||grid[y][x]=='*')&&grid[y][x-1]==' '&&grid[y][x+1]==' '
                &&grid[y][x+2]!=' '&&"-=|:+*/\\<>^v".indexOf(grid[y][x+2])<0) {
                grid[y][x]=' ';grid[y][x+1]='\u2022';x++;
            }
        }
        cw=(int)(10*opts.scale);ch=(int)(14*opts.scale);pixelWidth=width*cw;pixelHeight=height*ch;
        if((cw<=0||ch<2)&&!source.trim().isEmpty())throw new InvalidSize();
    }
    void printGrid() {
        StringBuilder s=new StringBuilder("    ");
        int n=((width+9)/10)*10;for(int x=0;x<n;x++)s.append(x%10);
        System.out.println(s);
        for(int y=0;y<height;y++)System.out.printf("%2d (%s)%n",y,new String(grid[y]));
    }
    char get(int x,int y){return x<0||x>=width||y<0||y>=height?' ':grid[y][x];}
    char get(Cell c){return get(c.x,c.y);}
    float px(int x){return x*cw+cw/2;}
    float py(int y){return y*ch+ch/2;}
    static ArrayList<Cell> rowOrder(Collection<Cell> cells) {
        ArrayList<Cell> list=new ArrayList<>(cells);list.sort(Comparator.comparingInt((Cell c)->c.y).thenComparingInt(c->c.x));return list;
    }
    static HashSet<Cell> orderedSet(Collection<Cell> cells) {
        HashSet<Cell> r=new HashSet<>();for(Cell c:rowOrder(cells))r.add(c);return r;
    }
    HashSet<Cell> neighbors(Cell c,Set<Cell> set) {
        HashSet<Cell> r=new HashSet<>();for(int k=0;k<4;k++){Cell n=c.at(DX[k],DY[k]);if(set.contains(n))r.add(n);}return r;
    }
    static int mask(char c) {
        switch(c) {
            case '-':case '=':return 12;
            case '|':case ':':return 3;
            case '+':case '*':case '/':case '\\':return 15;
            default:return 0;
        }
    }
    int rawDegree(Cell c) {
        int m=mask(get(c)),degree=0;
        for(int i=0;i<4;i++)if((m&(1<<i))!=0&&(mask(get(c.x+DX[i],c.y+DY[i]))&(1<<(i^1)))!=0)degree++;
        return degree;
    }
    void scanGrid() {
        textGrid=new char[height][];for(int y=0;y<height;y++)textGrid[y]=grid[y].clone();
        for(int y=0;y<height;y++) {
            String line=new String(grid[y]);
            Matcher mc=COLORS.matcher(line);
            while(mc.find()){markup.add(new Markup(mc.start(),y,mc.end()-mc.start(),mc.group().substring(1),true));Arrays.fill(textGrid[y],mc.start(),mc.end(),' ');}
            Matcher mt=TAGS.matcher(line);
            while(mt.find()){markup.add(new Markup(mt.start(),y,mt.end()-mt.start(),mt.group().substring(1,mt.group().length()-1),false));Arrays.fill(textGrid[y],mt.start(),mt.end(),' ');}
        }
        HashSet<Cell> potential=new HashSet<>();
        for(int y=0;y<height;y++)for(int x=0;x<width;x++) {
            char c=get(x,y);Cell p=new Cell(x,y);int degree=rawDegree(p);
            if(c=='<'||c=='>'||c=='^'||c=='v'&&"|:+*".indexOf(get(x,y-1))>=0) {arrows.add(p);textGrid[y][x]=' ';}
            if(c=='='||c==':'||c=='*')textGrid[y][x]=' ';
            if(c=='+'&&degree>0)textGrid[y][x]=' ';
            boolean ok=c=='-'||c=='|'||(c=='='||c==':')&&degree>0||c=='+'&&degree>=2||c=='*'&&degree>=1;
            if(c=='/'||c=='\\') {
                boolean n=(mask(get(x,y-1))&2)!=0,s=(mask(get(x,y+1))&1)!=0;
                boolean e=(mask(get(x+1,y))&8)!=0,w=(mask(get(x-1,y))&4)!=0;
                ok=c=='/'?(e&&s||n&&w):(n&&e||s&&w);
            }
            if(ok)potential.add(p);
        }
        // A junction needs two real incident line segments; adjacent loose markers
        // do not by themselves constitute a line.
        boolean changed;
        do {
            changed=false;ArrayList<Cell> remove=new ArrayList<>();
            for(Cell c:potential) {
                int n=0;int m=mask(get(c));
                for(int k=0;k<4;k++) {
                    Cell b=c.at(DX[k],DY[k]);
                    if(potential.contains(b)&&(m&(1<<k))!=0&&(mask(get(b))&(1<<(k^1)))!=0)n++;
                }
                char a=get(c);
                if(a=='+'&&n<2||(a=='='||a==':'||a=='*')&&n==0)remove.add(c);
                if(a=='*'&&n>0) {
                    boolean substantive=false;
                    for(Cell b:neighbors(c,potential))if(get(b)!='*')substantive=true;
                    if(!substantive)remove.add(c);
                }
            }
            if(!remove.isEmpty()){potential.removeAll(remove);changed=true;}
        }while(changed);
        for(Cell c:rowOrder(potential)){nodes.add(c);textGrid[c.y][c.x]=' ';if(get(c)=='*')markers.add(c);}
        for(Cell c:rowOrder(nodes)) {
            HashSet<Cell> adj=new HashSet<>();
            for(int k=0;k<4;k++){Cell n=c.at(DX[k],DY[k]);if(nodes.contains(n)&&(mask(get(c))&(1<<k))!=0&&(mask(get(n))&(1<<(k^1)))!=0)adj.add(n);}
            graph.put(c,adj);
        }
    }
    static int direction(Cell a,Cell b) {return b.x>a.x?0:b.y>a.y?1:b.x<a.x?2:3;}
    static long signedArea(List<Cell> path) {
        long a=0;for(int i=0;i<path.size();i++){Cell p=path.get(i),q=path.get((i+1)%path.size());a+=(long)p.x*q.y-(long)p.y*q.x;}return a;
    }
    HashMap<Edge,Integer> faceEdges=new HashMap<>();
    void findFaces() {
        HashSet<Directed> visited=new HashSet<>();
        for(Cell a:rowOrder(nodes))for(Cell b:graph.get(a)) {
            if(visited.contains(new Directed(a,b)))continue;
            ArrayList<Cell> ring=new ArrayList<>();Cell from=a,to=b;int guard=0;
            do {
                Directed d=new Directed(from,to);if(visited.contains(d))break;
                visited.add(d);ring.add(from);
                int incoming=direction(from,to);Cell next=null;
                int[] turns={1,0,3,2};
                for(int t:turns) {
                    int dir=(incoming+t)%4;
                    for(Cell p:graph.get(to))if(direction(to,p)==dir){next=p;break;}
                    if(next!=null)break;
                }
                if(next==null)break;
                from=to;to=next;
                if(++guard>nodes.size()*4+10)break;
            }while(!(from.equals(a)&&to.equals(b)));
            if(ring.size()<4||signedArea(ring)<=0)continue;
            Figure f=new Figure(true);f.cells.addAll(ring);
            faces.add(f);
            for(int i=0;i<ring.size();i++){Edge e=new Edge(ring.get(i),ring.get((i+1)%ring.size()));faceEdges.put(e,faceEdges.getOrDefault(e,0)+1);}
        }
        // Discover faces in the same spatial order used for other components.
        HashMap<Cell,Integer> ranks=new HashMap<>();int rank=0;for(Cell c:nodes)ranks.put(c,rank++);
        faces.sort(Comparator.comparingInt(f->f.cells.stream().mapToInt(c->ranks.get(c)).min().orElse(0)));
        for(Figure f:faces) {
            ArrayList<Cell> path=traceRing(f.cells);
            f.cells=path;
            f.dashed=containsDash(path);
            makeVertices(f,path,true);
            if(!options.noSeparation)separate(f,path);
            f.path=polygonPath(f);
            f.area=(float)(f.path.getBounds2D().getWidth()*f.path.getBounds2D().getHeight());
        }
    }
    ArrayList<Cell> traceRing(Collection<Cell> ring) {
        HashSet<Cell> set=orderedSet(ring);Cell start=set.iterator().next(),cur=start,prev=null;
        ArrayList<Cell> out=new ArrayList<>();
        // Use only the edges of this particular face at junctions.
        HashMap<Cell,HashSet<Cell>> local=new HashMap<>();
        ArrayList<Cell> cyc=new ArrayList<>(ring);
        for(int i=0;i<cyc.size();i++) {
            Cell c=cyc.get(i),left=cyc.get((i+cyc.size()-1)%cyc.size()),right=cyc.get((i+1)%cyc.size());
            HashSet<Cell> near=new HashSet<>();
            for(int k=0;k<4;k++){Cell n=c.at(DX[k],DY[k]);if(n.equals(left)||n.equals(right))near.add(n);}
            local.put(c,near);
        }
        do {
            out.add(cur);HashSet<Cell> near=local.get(cur);Cell next=null;
            if(near==null)break;
            for(Cell c:near)if(!c.equals(prev)){next=c;break;}
            if(next==null)break;prev=cur;cur=next;
        }while(!cur.equals(start)&&out.size()<=set.size()+1);
        return out;
    }
    boolean containsDash(Collection<Cell> cells){for(Cell c:cells)if(get(c)=='='||get(c)==':')return true;return false;}
    boolean corner(Cell before,Cell here,Cell after){return before.x!=after.x&&before.y!=after.y;}
    void makeVertices(Figure f,List<Cell> cells,boolean closed) {
        for(int i=0;i<cells.size();i++) {
            Cell c=cells.get(i);boolean end=!closed&&(i==0||i==cells.size()-1);
            boolean turn=!end&&corner(cells.get((i+cells.size()-1)%cells.size()),c,cells.get((i+1)%cells.size()));
            if(end||turn)f.vertices.add(new Vertex(px(c.x),py(c.y),!end&&(options.round||get(c)=='/'||get(c)=='\\')));
        }
    }
    void separate(Figure f,List<Cell> cells) {
        if(f.vertices.size()<3)return;
        boolean shared=false;for(int i=0;i<cells.size();i++)if(faceEdges.getOrDefault(new Edge(cells.get(i),cells.get((i+1)%cells.size())),0)>1)shared=true;
        if(!shared)return;
        boolean clockwise=signedArea(cells)>0;
        int n=f.vertices.size();ArrayList<Vertex> old=new ArrayList<>();for(Vertex v:f.vertices)old.add(v.copy());
        float gap=cw/5f;
        float[] ox=new float[n],oy=new float[n];
        for(int i=0;i<n;i++) {
            Vertex a=old.get(i),b=old.get((i+1)%n);boolean isShared=false;
            for(int j=0;j<cells.size();j++) {
                Cell c=cells.get(j),d=cells.get((j+1)%cells.size());
                if(faceEdges.getOrDefault(new Edge(c,d),0)<2)continue;
                float mx=(px(c.x)+px(d.x))/2,my=(py(c.y)+py(d.y))/2;
                if(a.x==b.x&&mx==a.x&&my>=Math.min(a.y,b.y)&&my<=Math.max(a.y,b.y)
                    ||a.y==b.y&&my==a.y&&mx>=Math.min(a.x,b.x)&&mx<=Math.max(a.x,b.x)){isShared=true;break;}
            }
            if(isShared) {
                float dx=Math.signum(b.x-a.x),dy=Math.signum(b.y-a.y),sign=clockwise?1:-1;
                ox[i]=-dy*gap*sign;oy[i]=dx*gap*sign;
            }
        }
        for(int i=0;i<n;i++) {
            int prev=(i+n-1)%n;Vertex v=f.vertices.get(i);
            v.x+=ox[i]+ox[prev];v.y+=oy[i]+oy[prev];
        }
    }
    void findOpenPaths() {
        HashMap<Cell,HashSet<Cell>> open=new HashMap<>();HashSet<Cell> remaining=new HashSet<>();
        for(Cell c:rowOrder(nodes)) {
            HashSet<Cell> near=new HashSet<>();
            for(Cell b:graph.get(c))if(!faceEdges.containsKey(new Edge(c,b)))near.add(b);
            if(!near.isEmpty()||graph.get(c).isEmpty()) {open.put(c,near);remaining.add(c);}
        }
        HashSet<Edge> walked=new HashSet<>();
        while(!remaining.isEmpty()) {
            Cell seed=remaining.iterator().next();HashSet<Cell> component=new HashSet<>();ArrayDeque<Cell> q=new ArrayDeque<>();q.add(seed);component.add(seed);
            while(!q.isEmpty()){Cell c=q.removeFirst();for(Cell b:open.get(c))if(component.add(b))q.add(b);}
            remaining.removeAll(component);
            if(component.size()==1) {
                Cell c=component.iterator().next();if(get(c)=='-'||get(c)=='|')singleCell(c);continue;
            }
            HashSet<Cell> ends=new HashSet<>();for(Cell c:rowOrder(component))if(open.get(c).size()==1)ends.add(c);
            if(ends.isEmpty())continue;
            Cell start=ends.iterator().next();
            walkBranch(start,null,open,walked);
        }
    }
    void walkBranch(Cell start,Cell previous,HashMap<Cell,HashSet<Cell>> open,Set<Edge> walked) {
        ArrayList<Cell> path=new ArrayList<>();path.add(start);Cell cur=start,prev=previous;
        while(true) {
            ArrayList<Cell> next=new ArrayList<>();for(Cell c:open.get(cur))if(!c.equals(prev)&&!walked.contains(new Edge(cur,c)))next.add(c);
            if(next.isEmpty())break;
            if(next.size()>1) {
                for(Cell c:next) {
                    if(walked.contains(new Edge(cur,c)))continue;
                    walked.add(new Edge(cur,c));walkFromEdge(cur,c,open,walked);
                }
                break;
            }
            Cell n=next.get(0);walked.add(new Edge(cur,n));prev=cur;cur=n;path.add(cur);
        }
        if(path.size()>1)addOpen(path);
    }
    void walkFromEdge(Cell start,Cell second,HashMap<Cell,HashSet<Cell>> open,Set<Edge> walked) {
        ArrayList<Cell> path=new ArrayList<>();path.add(start);path.add(second);Cell prev=start,cur=second;
        while(true) {
            ArrayList<Cell> next=new ArrayList<>();for(Cell c:open.get(cur))if(!c.equals(prev)&&!walked.contains(new Edge(cur,c)))next.add(c);
            if(next.isEmpty())break;
            if(next.size()>1) {
                for(Cell c:next)if(!walked.contains(new Edge(cur,c))){walked.add(new Edge(cur,c));walkFromEdge(cur,c,open,walked);}
                break;
            }
            Cell n=next.get(0);walked.add(new Edge(cur,n));prev=cur;cur=n;path.add(cur);
        }
        addOpen(path);
    }
    void singleCell(Cell c) {
        Figure f=new Figure(false);f.cells.add(c);
        if(get(c)=='-'){f.vertices.add(new Vertex(c.x*cw,py(c.y),false));f.vertices.add(new Vertex((c.x+1)*cw-1,py(c.y),false));}
        else {f.vertices.add(new Vertex(px(c.x),c.y*ch,false));f.vertices.add(new Vertex(px(c.x),(c.y+1)*ch-1,false));}
        extendEnds(f,c,c);f.path=polygonPath(f);figures.add(f);
    }
    void addOpen(ArrayList<Cell> cells) {
        Figure f=new Figure(false);f.cells.addAll(cells);f.dashed=containsDash(cells);makeVertices(f,cells,false);
        if(f.vertices.size()<2)return;
        extendEnds(f,cells.get(0),cells.get(cells.size()-1));
        f.path=polygonPath(f);f.area=(float)(f.path.getBounds2D().getWidth()*f.path.getBounds2D().getHeight());figures.add(f);
    }
    void extendEnds(Figure f,Cell start,Cell end) {
        if(f.vertices.isEmpty())return;
        for(Cell a:arrows) {
            char c=get(a);int sx=c=='>'?1:c=='<'?-1:0,sy=c=='v'?1:c=='^'?-1:0;
            if(start.x+sx==a.x&&start.y+sy==a.y){Vertex v=f.vertices.get(0);v.x=px(a.x);v.y=py(a.y);}
            if(end.x+sx==a.x&&end.y+sy==a.y){Vertex v=f.vertices.get(f.vertices.size()-1);v.x=px(a.x);v.y=py(a.y);}
        }
    }
    void makeArrows() {
        for(Cell c:arrows) {
            Figure f=new Figure(true);f.arrow=true;f.color=Color.BLACK;
            float x=c.x*cw,y=c.y*ch,cx=px(c.x),cy=py(c.y);
            switch(get(c)) {
                case '>':f.vertices.add(new Vertex(x,y,false));f.vertices.add(new Vertex(x+cw,cy,false));f.vertices.add(new Vertex(x,y+ch,false));break;
                case '<':f.vertices.add(new Vertex(x+cw,y,false));f.vertices.add(new Vertex(x,cy,false));f.vertices.add(new Vertex(x+cw,y+ch,false));break;
                case '^':f.vertices.add(new Vertex(cx,y,false));f.vertices.add(new Vertex(x,y+ch,false));f.vertices.add(new Vertex(x+cw,y+ch,false));break;
                case 'v':f.vertices.add(new Vertex(x,y,false));f.vertices.add(new Vertex(cx,y+ch,false));f.vertices.add(new Vertex(x+cw,y,false));break;
            }
            f.path=polygonPath(f);f.area=cw*ch;figures.add(f);
        }
    }
    static Color parseColor(String s) {
        switch(s){case "RED":s="E32";break;case "GRE":s="9D9";break;case "BLU":s="55B";break;case "PNK":s="FAA";break;case "YEL":s="FF3";break;case "BLK":s="000";break;}
        return new Color(Integer.parseInt(s.substring(0,1),16)*17,Integer.parseInt(s.substring(1,2),16)*17,Integer.parseInt(s.substring(2,3),16)*17);
    }
    void applyMarkup() {
        for(Markup m:markup) {
            Figure best=null;
            for(Figure f:faces)if(f.path.contains(px(m.x),py(m.y))&&(best==null||f.area<best.area))best=f;
            if(best==null)continue;
            if(m.color)best.color=parseColor(m.value);else best.type=m.value;
        }
        for(Figure f:faces)if(!f.type.isEmpty())f.path=specialPath(f);
    }
    GeneralPath specialPath(Figure f) {
        Rectangle2D b=f.path.getBounds2D();float x=(float)b.getX(),y=(float)b.getY(),w=(float)b.getWidth(),h=(float)b.getHeight(),r=x+w,bottom=y+h;
        GeneralPath p=new GeneralPath();float offset=options.fixed?h/8f:cw/2;
        switch(f.type) {
            case "d":
                p.moveTo(x,y);p.lineTo(r,y);p.lineTo(r,bottom);
                p.quadTo(x+w*.66f,bottom-cw/2,x+w/2,bottom);p.quadTo(x+w*.34f,bottom+cw/2,x,bottom);p.closePath();break;
            case "s":
                p.moveTo(x,y);p.curveTo(x+w*.16f,y+ch/2,r-w*.16f,y+ch/2,r,y);
                p.curveTo(r-w*.16f,y-ch/2,x+w*.16f,y-ch/2,x,y);
                p.moveTo(x,y);p.lineTo(x,bottom);p.curveTo(x+w*.16f,bottom+cw,r-w*.16f,bottom+cw,r,bottom);p.lineTo(r,y);break;
            case "o": {
                double k=.5522847498307933;float cx=x+w/2,cy=y+h/2;double rx=w/2d,ry=h/2d;
                p.moveTo(cx,y);p.curveTo((float)(cx+rx*k),y,r,(float)(cy-ry*k),r,cy);
                p.curveTo(r,(float)(cy+ry*k),(float)(cx+rx*k),bottom,cx,bottom);
                p.curveTo((float)(cx-rx*k),bottom,x,(float)(cy+ry*k),x,cy);
                p.curveTo(x,(float)(cy-ry*k),(float)(cx-rx*k),y,cx,y);p.closePath();break;
            }
            case "c":p.moveTo(x,y+h/2);p.lineTo(x+w/2,y);p.lineTo(r,y+h/2);p.lineTo(x+w/2,bottom);p.closePath();break;
            case "mo":p.moveTo(x-offset,y);p.lineTo(r+offset,y);p.lineTo(r-offset,bottom);p.lineTo(x+offset,bottom);p.closePath();break;
            case "tr":p.moveTo(x+offset,y);p.lineTo(r-offset,y);p.lineTo(r+offset,bottom);p.lineTo(x-offset,bottom);p.closePath();break;
