            ArrayList<Label> group=new ArrayList<>();for(int i=0;i<runs.size();i++)if(root(parent,i)==id)group.add(runs.get(i));
            group.sort(Comparator.comparingInt((Label l)->l.row).thenComparingInt(l->l.col));groups.add(group);
        }
